-- ============================================================
-- Service Appointments (2026-11-05)
--
-- Workshop visits booked for Service-type enquiries (Service
-- Enquiries › Appointments page). Slots come from the default
-- Service Appointment time slot (Enquiry Setup › Time Slots).
--
-- Plain statements only : run in a NEW pgAdmin Query Tool with
-- F5. Safe to run again.
-- ============================================================

CREATE TABLE IF NOT EXISTS public."ServiceAppointments"
(
    "ServiceAppointmentId" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ServiceEnquiryId"     bigint                   NOT NULL,
    "EnquiryNo"            character varying(30)    NOT NULL DEFAULT '',
    "BranchId"             bigint                   NOT NULL,
    "BranchName"           character varying(150)   NOT NULL DEFAULT '',
    "AppointmentDate"      date                     NOT NULL,
    "SlotStart"            time                     NOT NULL,
    "SlotEnd"              time                     NOT NULL,
    "TimeSlotId"           bigint                   NULL,
    "Status"               character varying(20)    NOT NULL DEFAULT 'Booked',
    "StatusDate"           timestamp with time zone NULL,
    "CancelReason"         character varying(300)   NOT NULL DEFAULT '',
    "AdvisorUserId"        bigint                   NOT NULL DEFAULT 0,
    "AdvisorName"          character varying(150)   NOT NULL DEFAULT '',
    "Note"                 character varying(500)   NOT NULL DEFAULT '',
    "RescheduleCount"      integer                  NOT NULL DEFAULT 0,
    "IsDeleted"            boolean                  NOT NULL DEFAULT false,
    "DeletedBy"            bigint                   NULL,
    "DeletedDate"          timestamp with time zone NULL,
    "CreatedBy"            bigint                   NOT NULL,
    "CreatedDate"          timestamp with time zone NOT NULL DEFAULT now(),
    "ModifiedBy"           bigint                   NULL,
    "ModifiedDate"         timestamp with time zone NULL,
    CONSTRAINT "CK_ServiceAppointments_Status" CHECK ("Status" IN ('Booked', 'Confirmed', 'Arrived', 'NoShow', 'Cancelled'))
);

CREATE INDEX IF NOT EXISTS "IX_ServiceAppointments_Enquiry" ON public."ServiceAppointments" ("ServiceEnquiryId");

CREATE INDEX IF NOT EXISTS "IX_ServiceAppointments_Branch_Date" ON public."ServiceAppointments" ("BranchId", "AppointmentDate");

SELECT count(*) AS "ServiceAppointments" FROM public."ServiceAppointments";
